from lib import *
S = SS('l25')
steps = [
    step(".git/logs/HEAD 是一个文本文件,一行一次移动:旧 hash、新 hash、操作者(Alice <alice@example.com>)、时间戳、时区(+0800)、制表符,然后是说明。第一行旧 hash 全是 0(initial 提交之前 HEAD 不存在),说明是 commit (initial): 提交 1;之后 commit: 提交 2、checkout: moving from main to dev、checkout: moving from dev to main、reset: moving to HEAD~1。checkout 一次也写一行,新旧 hash 相同(位置没变,但当前分支变了)。", t=tl(S(1)), mark=lidx(S(1), '<全 0>', 'checkout: moving from main to dev', 'reset: moving to HEAD~1'), done=lidx(S(1), 'commit: 提交 2', 'checkout: moving from dev to main', 'cat .git/logs/HEAD'), kv=KV([['每行', '旧 hash、新 hash、操作者、时间戳、时区、说明'], ['checkout', '也写一行(hash 不变)'], ['initial', '旧 hash 全 0']], ['每行'])),
    step("每个分支有自己的 reflog:.git/logs/ 下有 HEAD 和 refs/heads/(dev、main 两个文件);git reflog show main 列出 main@{0}: reset…、main@{1}: commit: 提交 2、main@{2}: commit (initial): 提交 1。HEAD@{0} 是提交 1,HEAD@{1} 到 HEAD@{3} 都是提交 2。按时间引用:main@{5.minutes.ago} 和 main@{1.hour.ago} 都早于这个新仓库 reflog 的第一条记录,git 都给出最早的值(提交 1),并警告 log for 'main' only goes back to ……。", t=tl(S(2)), mark=lidx(S(2), 'only goes back to', 'main@{5.minutes.ago}'), done=lidx(S(2), 'main@{0}', 'main@{1}', 'main@{2}', 'HEAD@{3} →'), kv=KV([['logs/HEAD', 'HEAD 自己的移动记录'], ['logs/refs/heads/*', '每个分支各一份'], ['@{n} / @{时间}', '第 n 次之前 / 某个时间点的位置']], ['@{n} / @{时间}'])),
    step("哪些操作会写:commit、commit (amend)、checkout: moving from … to …、merge side(说明里带 Merge made by the 'ort' strategy.)、rebase 的 start / pick / finish 各一条(rebase (start): checkout side、rebase (pick): 主线提交、rebase (finish): returning to refs/heads/main)。共 10 条,HEAD@{0} 是最新的。reflog 不是只有“提交”,凡是移动了 HEAD 的操作都记。", t=tl(S(3)), mark=lidx(S(3), 'rebase (finish)', 'rebase (pick)', 'rebase (start)', 'merge side', 'commit (amend)'), done=lidx(S(3), 'checkout: moving', 'commit: 主线提交', 'commit (initial)'), kv=KV([['commit / amend', '各一条'], ['merge', '说明带合并策略'], ['rebase', 'start、每个 pick、finish'], ['checkout', '切换分支也记']], ['rebase'])),
    step("不是所有 ref 都有 reflog:分支有(heads 下有 main、side),标签默认没有(ls .git/logs/refs/tags 报 No such file);git init 在非裸仓库里写入了 core.logAllRefUpdates=true;用 -c core.logAllRefUpdates=always 创建标签 v2 之后 logs/refs/tags/v2 出现。裸仓库没有设置这个值,git update-ref 更新 refs/heads/main 之后连 logs 目录都没有——服务器端的裸仓库默认不记录 reflog。", t=tl(S(4)), mark=lidx(S(4), 'No such file', '裸仓库:未设置', 'ls: logs: No such file'), done=lidx(S(4), 'heads', 'always', '  true', '  v2'), kv=KV([['分支', '有 reflog'], ['标签', '默认没有,logAllRefUpdates=always 才有'], ['裸仓库', '默认不记录']], ['裸仓库'])),
    step("过期规则:在 HEAD 的 reflog 里造出不同年龄的条目(A 120 天前、B 100 天前、切换到 tmp 100 天前、U1 40 天前、U2 20 天前、切回 main 10 天前、C 5 天前,tmp 分支删掉所以 U1、U2 不可达),执行 git reflog expire --all(默认:可达条目 90 天,不可达条目 30 天)。之后只剩 3 条:C(5 天前)、checkout 回 main(10 天前)、U2(20 天前)。A(120 天,可达但超过 90 天)和 B(100 天)被删;100 天前的 checkout 条目被删;U1(40 天,不可达且超过 30 天)被删;U2(20 天,不可达但没到 30 天)保留。", t=tl(S(5)), mark=lidx(S(5), 'git reflog expire --all'), done=lidx(S(5), 'C-5天前', 'U2-20天前', 'U1-40天前', 'A-120天前', 'B-100天前'), b=bars([['A:120 天(可达)', 120, '被删(> 90)'], ['B:100 天(可达)', 100, '被删(> 90)'], ['U1:40 天(不可达)', 40, '被删(> 30)'], ['U2:20 天(不可达)', 20, '保留'], ['C:5 天(可达)', 5, '保留']], 120, mark=[0, 1, 2], done=[3, 4]), kv=KV([['可达的提交', '条目保留 90 天(gc.reflogExpire)'], ['不可达的提交', '条目保留 30 天(gc.reflogExpireUnreachable)'], ['expire --expire=now', '立即清空']], ['不可达的提交'])),
    step("reflog 是 reset --hard 的后悔药:reset --hard HEAD~2 后只剩提交 1,git reflog 里 HEAD@{1} 是 commit: 提交 3;git reset --hard HEAD@{1} 之后三个提交全回来了。反过来,git reflog expire --expire=now --all 之后 git reflog 一行也没有(wc -l 为 0),git reset --hard HEAD@{1} 报 fatal: log for HEAD is empty——退路没有了(提交对象本身还在,要靠 fsck 找,见前面 fsck 一篇)。", t=tl(S(6)), mark=lidx(S(6), 'log for HEAD is empty', '         0'), done=lidx(S(6), 'HEAD~2', 'HEAD@{1}: commit: 提交 3', '提交 3'), kv=KV([['撤销 reset', 'git reset --hard HEAD@{1}'], ['expire --expire=now', '之后无法再用 HEAD@{n}'], ['对象仍在', '直到 gc 清理']], ['撤销 reset'])),
]
A = mkarti('l25', 25, 'Git,reflog,HEAD@{n},过期,gc,真实验证,动画演示',
    '在真实仓库里看 reflog:.git/logs/HEAD 和每个分支一份的文本文件,记录 commit、amend、checkout、merge、rebase 的每次移动;分支有、标签默认没有、裸仓库默认没有;用造出不同年龄的条目验证 git reflog expire 默认保留可达的 90 天、不可达的 30 天;用 HEAD@{1} 撤销 reset --hard,expire --expire=now 之后就没有退路。',
    'reflog 到底记录了什么、记多久?这篇直接读 .git/logs 下的文件,看哪些操作会写、哪些 ref 有,再造出 120 天到 5 天前的各种条目,验证默认的过期规则,最后演示用它撤销 reset --hard。',
    [('90 / 30 天', 'git reflog expire 的默认保留期:可达的提交条目 90 天,不可达的 30 天'), ('3 条', '造出的 7 条 HEAD reflog 条目在默认 expire 之后剩下的条数'), ('0', 'git reflog expire --expire=now --all 之后 git reflog 的行数,HEAD@{n} 全部失效')],
    [('文件格式', '<p>reflog 就是 <code>.git/logs/HEAD</code> 和 <code>.git/logs/refs/heads/&lt;分支&gt;</code> 这样的文本文件,一行一次移动:旧 hash、新 hash、操作者、时间戳、时区、说明。HEAD 有一份,每个分支一份。</p>'),
     ('引用方式', '<p><code>HEAD@{n}</code> 是第 n 次移动之前的位置,<code>main@{5.minutes.ago}</code> 按时间取。所要的时间早于该 reflog 的第一条记录时(实验里的仓库刚建好,5 分钟前就已经算“更早”),git 给出最早的一条并警告。</p>'),
     ('会记什么', '<p>凡是移动 ref 的操作:commit、amend、checkout、merge、rebase 的每一步、reset 等等,说明里写了是哪种操作,方便在找回时辨认。</p>'),
     ('谁有 reflog', '<p>分支有,标签默认没有(<code>core.logAllRefUpdates=always</code> 才有),服务器端的裸仓库默认不记录。所以服务器上误删的东西不能指望 reflog。</p>'),
     ('过期', '<p>reflog 不是永久的:可达提交的条目保留 90 天(<code>gc.reflogExpire</code>),不可达的保留 30 天(<code>gc.reflogExpireUnreachable</code>)。实验里 120 天前、100 天前的可达条目和 40 天前的不可达条目被删,20 天前的不可达条目保留。<code>git gc</code> 会执行这个 expire。</p>'),
     ('用法与底线', '<p>reset --hard 后用 <code>HEAD@{1}</code> 即可回到之前的位置;一旦手工 <code>reflog expire --expire=now</code>,就不能再这样用了,对象虽然还在,只能靠 <code>git fsck</code> 去找。</p>')],
    steps,
    [ENV_I_GIT + '。这一篇的提交使用真实时间;“120 天前、100 天前……”是用 GIT_COMMITTER_DATE 把 reflog 条目的时间写成过去的时间构造的,没有真的等待;相对时间(5 days ago、3 weeks ago)随运行日期变化,取值范围在本文中保持稳定',
     '没有验证:gc.reflogExpire 与 gc.reflogExpireUnreachable 改成其它值;git reflog expire 的 --stale-fix、--rewrite、--updateref;worktree 各自的 reflog;reflog 本身占的空间;core.logAllRefUpdates=false 的行为'],
    'reflog')
